{var $v_tone = ($p['tone'] ?? 'default')}
{var $v_density = ($p['density'] ?? 'default')}
{var $v_landmarkLabel = ($p['landmarkLabel'] ?? null)}
{var $v_askedCols = (ui_t(ui_and([ui_eq($v_item, 'chip'), ui_eq($v_cols, '6')])) ? '2-6' : (ui_t(ui_eq($v_cols, '2')) ? '2' : (ui_t(ui_eq($v_cols, '3')) ? '2-3' : (ui_t(ui_eq($v_cols, '4')) ? '2-4' : '3-6'))))}
{var $v_wallCols = ui_fit_cols($v_askedCols, ui_len($v_features))}
{capture $c_4}
  {capture $c_3}
    {foreach ui_l($v_features) as $v_f}
      {capture $c_2}
        {=ui_include('ui/lucide-icon/lucide-icon.latte', ['p' => ['Name' => ui_s(ui_get($v_f, ['icon'])), 'Size' => ui_i((ui_t(ui_eq($v_item, 'tile')) ? 24 : 16))]])|noescape}
        {capture $c_1}
          {=ui_text(ui_get($v_f, ['title']))}
        {/capture}
        {=ui_include('ui/text/text.latte', ['p' => ['Size' => 'sm', 'Weight' => 'semibold'], 'children' => $c_1])|noescape}
      {/capture}
      {=ui_include('ui/box/box.latte', ['p' => ['Class' => ui_s(ui_cnv(['flex items-center gap-2', 'rounded bg-card inset-ring inset-ring-border', (ui_t(ui_eq($v_item, 'tile')) ? ui_cnv(['flex-col justify-center text-center', (ui_t(ui_eq($v_density, 'compact')) ? 'p-4' : 'p-6')]) : 'px-4 py-2')])), 'Attrs' => ui_attrs(['data-testid', 'item'])], 'children' => $c_2])|noescape}
    {/foreach}
  {/capture}
  {=ui_include('ui/grid/grid.latte', ['p' => ['Cols' => ui_s($v_wallCols), 'Class' => 'gap-4', 'Attrs' => ui_attrs(['data-testid', 'items'])], 'children' => $c_3])|noescape}
{/capture}
{=ui_include('blocks/section-frame.latte', ['p' => ['id' => $v_id, 'title' => $v_title, 'tone' => $v_tone, 'density' => $v_density, 'landmarkLabel' => $v_landmarkLabel], 'children' => $c_4])|noescape}
